//
// --- Golden-fixture parity with the TypeScript implementation ---
//
// Fixtures under testdata/ were generated by executing the ACTUAL enbox
// TypeScript implementation (dwn-sdk-js + agent sources at
// ~/src/enboxorg/enbox) with a fixed Ed25519 key and fixed timestamps:
//
//	bun scratchpad/fixtures/generate.ts internal/dwn/testdata
//
// (script kept in the session scratchpad; the generatedBy field in each
// fixture file records the provenance).
//
// The parity assertions cover: byte-identical descriptors (deep JSON
// equality AND equal descriptor CIDs), byte-identical signature payloads,
// and equal CIDs computed over the full TS-signed message. Full-JWS byte
// equality is NOT asserted: dwn-sdk-js serializes the protected header as
// {"kid","alg"} while meshd emits {"alg","kid"} — both are valid JWS and the
// server never compares header bytes, but the signatures differ.
//

type messagesWireFixtureFile struct {
	GeneratedBy          string                `json:"generatedBy"`
	DID                  string                `json:"did"`
	Ed25519SeedBase64URL string                `json:"ed25519SeedBase64Url"`
	Fixtures             []messagesWireFixture `json:"fixtures"`
}

type messagesWireFixture struct {
	Name                      string          `json:"name"`
	Inputs                    json.RawMessage `json:"inputs"`
	Message                   json.RawMessage `json:"message"`
	Descriptor                json.RawMessage `json:"descriptor"`
	SignaturePayloadBase64URL string          `json:"signaturePayloadBase64Url"`
	DescriptorCid             string          `json:"descriptorCid"`
	MessageCid                string          `json:"messageCid"`
}

type messagesWireFixtureInputs struct {
	MessageTimestamp   string           `json:"messageTimestamp"`
	Filters            []MessagesFilter `json:"filters"`
	PermissionGrantIDs []string         `json:"permissionGrantIds"`
	Cursor             *ProgressToken   `json:"cursor"`
	Limit              int              `json:"limit"`
	CidsOnly           bool             `json:"cidsOnly"`
	MessageCid         string           `json:"messageCid"`
}

func loadMessagesWireFixtures(t *testing.T) (*Signer, []messagesWireFixture) {
	t.Helper()
	data, err := os.ReadFile("testdata/messages_wire_fixtures.json")
	if err != nil {
		t.Fatalf("reading fixtures: %v", err)
	}
	var file messagesWireFixtureFile
	if err := json.Unmarshal(data, &file); err != nil {
		t.Fatalf("parsing fixtures: %v", err)
	}
	seed, err := base64.RawURLEncoding.DecodeString(file.Ed25519SeedBase64URL)
	if err != nil {
		t.Fatalf("decoding fixture seed: %v", err)
	}
	signer := &Signer{
		DID:        file.DID,
		PrivateKey: ed25519.NewKeyFromSeed(seed),
	}
	return signer, file.Fixtures
}

func TestMessagesBuildersMatchTypeScriptFixtures(t *testing.T) {
	signer, fixtures := loadMessagesWireFixtures(t)
	if len(fixtures) == 0 {
		t.Fatal("no fixtures loaded")
	}

	for _, fixture := range fixtures {
		t.Run(fixture.Name, func(t *testing.T) {
			var inputs messagesWireFixtureInputs
			if err := json.Unmarshal(fixture.Inputs, &inputs); err != nil {
				t.Fatalf("parsing inputs: %v", err)
			}

			var (
				msg *Message
				err error
			)
			var fixtureMethod struct {
				Descriptor struct {
					Method string `json:"method"`
				} `json:"descriptor"`
			}
			if err := json.Unmarshal(fixture.Message, &fixtureMethod); err != nil {
				t.Fatalf("parsing fixture message method: %v", err)
			}
			switch fixtureMethod.Descriptor.Method {
			case "Query":
				msg, err = BuildMessagesQuery(signer, MessagesQueryOptions{
					Filters:            inputs.Filters,
					PermissionGrantIDs: inputs.PermissionGrantIDs,
					Cursor:             inputs.Cursor,
					Limit:              inputs.Limit,
					CidsOnly:           inputs.CidsOnly,
					MessageTimestamp:   inputs.MessageTimestamp,
				})
			case "Read":
				msg, err = BuildMessagesRead(signer, MessagesReadOptions{
					MessageCID:         inputs.MessageCid,
					PermissionGrantIDs: inputs.PermissionGrantIDs,
					MessageTimestamp:   inputs.MessageTimestamp,
				})
			case "Subscribe":
				msg, err = BuildMessagesSubscribe(signer, MessagesSubscribeOptions{
					Filters:            inputs.Filters,
					PermissionGrantIDs: inputs.PermissionGrantIDs,
					Cursor:             inputs.Cursor,
					MessageTimestamp:   inputs.MessageTimestamp,
				})
			default:
				t.Fatalf("unknown fixture method %q", fixtureMethod.Descriptor.Method)
			}
			if err != nil {
				t.Fatalf("building message: %v", err)
			}

			// 1. Descriptors must be identical (deep JSON equality).
			var wantDescriptor any
			if err := json.Unmarshal(fixture.Descriptor, &wantDescriptor); err != nil {
				t.Fatalf("parsing fixture descriptor: %v", err)
			}
			gotDescriptorJSON, err := json.Marshal(msg.Descriptor)
			if err != nil {
				t.Fatalf("marshaling built descriptor: %v", err)
			}
			var gotDescriptor any
			if err := json.Unmarshal(gotDescriptorJSON, &gotDescriptor); err != nil {
				t.Fatalf("round-tripping built descriptor: %v", err)
			}
			if !reflect.DeepEqual(gotDescriptor, wantDescriptor) {
				t.Errorf("descriptor mismatch:\n got: %s\nwant: %s", gotDescriptorJSON, fixture.Descriptor)
			}

			// 2. Signature payloads must be byte-identical.
			if got := msg.Authorization.Signature.Payload; got != fixture.SignaturePayloadBase64URL {
				gotBytes, _ := base64.RawURLEncoding.DecodeString(got)
				wantBytes, _ := base64.RawURLEncoding.DecodeString(fixture.SignaturePayloadBase64URL)
				t.Errorf("signature payload mismatch:\n got: %s\nwant: %s", gotBytes, wantBytes)
			}

			// 3. The Go descriptor CID must match the TS descriptor CID.
			gotDescriptorCid, err := ComputeCID(msg.Descriptor)
			if err != nil {
				t.Fatalf("computing descriptor CID: %v", err)
			}
			if gotDescriptorCid != fixture.DescriptorCid {
				t.Errorf("descriptor CID = %s, want %s", gotDescriptorCid, fixture.DescriptorCid)
			}

			// 4. Go's CID discipline must reproduce the TS message CID over
			// the TS-signed message (dag-cbor, CIDv1, sha2-256).
			var fixtureMessage map[string]any
			if err := json.Unmarshal(fixture.Message, &fixtureMessage); err != nil {
				t.Fatalf("parsing fixture message: %v", err)
			}
			gotMessageCid, err := ComputeCID(fixtureMessage)
			if err != nil {
				t.Fatalf("computing message CID: %v", err)
			}
			if gotMessageCid != fixture.MessageCid {
				t.Errorf("message CID over TS message = %s, want %s", gotMessageCid, fixture.MessageCid)
			}
		})
	}
}

type grantIDsFixtureFile struct {
	Vectors []struct {
		Name  string `json:"name"`
		Input struct {
			PermissionGrantID  string   `json:"permissionGrantId"`
			PermissionGrantIDs []string `json:"permissionGrantIds"`
		} `json:"input"`
		Canonical []string `json:"canonical"`
		ErrorCode string   `json:"errorCode"`
	} `json:"vectors"`
}

func TestPermissionGrantIDCanonicalizationMatchesTypeScriptFixtures(t *testing.T) {
	data, err := os.ReadFile("testdata/grant_ids_fixtures.json")
	if err != nil {
		t.Fatalf("reading fixtures: %v", err)
	}
	var file grantIDsFixtureFile
	if err := json.Unmarshal(data, &file); err != nil {
		t.Fatalf("parsing fixtures: %v", err)
	}
	if len(file.Vectors) == 0 {
		t.Fatal("no vectors loaded")
	}

	wantErrs := map[string]error{
		"MessagePermissionGrantIdsEmpty":                  ErrPermissionGrantIDsEmpty,
		"MessagePermissionGrantCreateInvocationAmbiguous": ErrPermissionGrantInvocationAmbiguous,
	}

	for _, vector := range file.Vectors {
		t.Run(vector.Name, func(t *testing.T) {
			canonical, err := NormalizePermissionGrantInvocation(vector.Input.PermissionGrantID, vector.Input.PermissionGrantIDs)
			if vector.ErrorCode != "" {
				wantErr, ok := wantErrs[vector.ErrorCode]
				if !ok {
					t.Fatalf("fixture uses unmapped error code %q", vector.ErrorCode)
				}
				if !errors.Is(err, wantErr) {
					t.Fatalf("error = %v, want %v", err, wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("NormalizePermissionGrantInvocation: %v", err)
			}
			if !reflect.DeepEqual(canonical, vector.Canonical) {
				t.Errorf("canonical = %q, want %q", canonical, vector.Canonical)
			}
		})
	}
}

func TestValidateCanonicalPermissionGrantIDs(t *testing.T) {
	if err := ValidateCanonicalPermissionGrantIDs(nil); err != nil {
		t.Errorf("nil list: %v", err)
	}
	if err := ValidateCanonicalPermissionGrantIDs([]string{"a", "b"}); err != nil {
		t.Errorf("canonical list: %v", err)
	}
	if err := ValidateCanonicalPermissionGrantIDs([]string{"b", "a"}); !errors.Is(err, ErrPermissionGrantIDsNotCanonical) {
		t.Errorf("unsorted list error = %v, want ErrPermissionGrantIDsNotCanonical", err)
	}
	if err := ValidateCanonicalPermissionGrantIDs([]string{"a", "a"}); !errors.Is(err, ErrPermissionGrantIDsNotCanonical) {
		t.Errorf("duplicated list error = %v, want ErrPermissionGrantIDsNotCanonical", err)
	}
	if err := ValidateCanonicalPermissionGrantIDs([]string{}); !errors.Is(err, ErrPermissionGrantIDsEmpty) {
		t.Errorf("empty list error = %v, want ErrPermissionGrantIDsEmpty", err)
	}
}

//
// --- Builder unit tests ---
