func TestBuildMessagesQueryDescriptorShape(t *testing.T) {
	signer := newTestSigner(t)

	t.Run("filters always present", func(t *testing.T) {
		msg, err := BuildMessagesQuery(signer, MessagesQueryOptions{})
		if err != nil {
			t.Fatalf("BuildMessagesQuery: %v", err)
		}
		filters, ok := msg.Descriptor["filters"].([]any)
		if !ok || len(filters) != 0 {
			t.Fatalf("filters = %#v, want empty array", msg.Descriptor["filters"])
		}
		wire, err := json.Marshal(msg.Descriptor)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		var onWire map[string]json.RawMessage
		if err := json.Unmarshal(wire, &onWire); err != nil {
			t.Fatalf("unmarshal: %v", err)
		}
		if string(onWire["filters"]) != "[]" {
			t.Errorf("wire filters = %s, want []", onWire["filters"])
		}
		for _, absent := range []string{"limit", "cidsOnly", "cursor", "permissionGrantIds"} {
			if _, ok := onWire[absent]; ok {
				t.Errorf("zero-value field %q must be omitted", absent)
			}
		}
	})

	t.Run("grant IDs canonicalized in descriptor and payload", func(t *testing.T) {
		msg, err := BuildMessagesQuery(signer, MessagesQueryOptions{
			PermissionGrantIDs: []string{"b", "a", "b"},
		})
		if err != nil {
			t.Fatalf("BuildMessagesQuery: %v", err)
		}
		want := []string{"a", "b"}
		got, ok := msg.Descriptor["permissionGrantIds"].([]string)
		if !ok || !reflect.DeepEqual(got, want) {
			t.Errorf("descriptor permissionGrantIds = %#v, want %v", msg.Descriptor["permissionGrantIds"], want)
		}
		payloadBytes, err := base64.RawURLEncoding.DecodeString(msg.Authorization.Signature.Payload)
		if err != nil {
			t.Fatalf("decoding payload: %v", err)
		}
		var payload struct {
			DescriptorCid      string   `json:"descriptorCid"`
			PermissionGrantIDs []string `json:"permissionGrantIds"`
		}
		if err := json.Unmarshal(payloadBytes, &payload); err != nil {
			t.Fatalf("parsing payload: %v", err)
		}
		if !reflect.DeepEqual(payload.PermissionGrantIDs, want) {
			t.Errorf("payload permissionGrantIds = %v, want %v", payload.PermissionGrantIDs, want)
		}
		wantCid, err := ComputeCID(msg.Descriptor)
		if err != nil {
			t.Fatalf("ComputeCID: %v", err)
		}
		if payload.DescriptorCid != wantCid {
			t.Errorf("payload descriptorCid = %s, want %s", payload.DescriptorCid, wantCid)
		}
	})

	t.Run("explicit empty grant list rejected", func(t *testing.T) {
		_, err := BuildMessagesQuery(signer, MessagesQueryOptions{PermissionGrantIDs: []string{}})
		if !errors.Is(err, ErrPermissionGrantIDsEmpty) {
			t.Errorf("error = %v, want ErrPermissionGrantIDsEmpty", err)
		}
	})

	t.Run("empty filter rejected", func(t *testing.T) {
		if _, err := BuildMessagesQuery(signer, MessagesQueryOptions{Filters: []MessagesFilter{{}}}); err == nil {
			t.Error("empty filter must be rejected (schema minProperties: 1)")
		}
		if _, err := BuildMessagesQuery(signer, MessagesQueryOptions{
			Filters: []MessagesFilter{{MessageTimestamp: &MessagesTimestampRange{}}},
		}); err == nil {
			t.Error("empty messageTimestamp range must be rejected")
		}
	})

	t.Run("invalid cursor rejected", func(t *testing.T) {
		if _, err := BuildMessagesQuery(signer, MessagesQueryOptions{Cursor: &ProgressToken{StreamID: "s"}}); err == nil {
			t.Error("invalid cursor must be rejected")
		}
	})
}

