//
// --- Client method tests ---
//

// messagesTestServer returns a Client pointed at an httptest server that
// responds to each request with the given responder.
func messagesTestServer(t *testing.T, responder func(w http.ResponseWriter, req *JsonRpcRequest)) *Client {
	t.Helper()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var rpcReq JsonRpcRequest
		if err := json.Unmarshal([]byte(r.Header.Get("dwn-request")), &rpcReq); err != nil {
			t.Errorf("parsing dwn-request header: %v", err)
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		responder(w, &rpcReq)
	}))
	t.Cleanup(server.Close)
	return NewClient(server.URL, newTestSigner(t))
}

func writeJSONRPCReply(w http.ResponseWriter, id string, reply any) {
	response := map[string]any{
		"jsonrpc": "2.0",
		"id":      id,
		"result":  map[string]any{"reply": reply},
	}
	_ = json.NewEncoder(w).Encode(response)
}

func TestClientMessagesQueryParsesReply(t *testing.T) {
	client := messagesTestServer(t, func(w http.ResponseWriter, req *JsonRpcRequest) {
		desc := req.Params.Message.Descriptor
		if desc["interface"] != "Messages" || desc["method"] != "Query" {
			t.Errorf("descriptor = %v, want Messages/Query", desc)
		}
		writeJSONRPCReply(w, req.ID, map[string]any{
			"status": map[string]any{"code": 200, "detail": "OK"},
			"entries": []map[string]any{
				{
					"seq":               "7",
					"messageCid":        "bafycid1",
					"isLatestBaseState": true,
					"protocol":          "https://example.com/protocols/mesh",
					"message":           map[string]any{"descriptor": map[string]any{"interface": "Records"}},
					"encodedData":       "aGVsbG8",
				},
				{
					// cidsOnly-style entry: message omitted.
					"seq":               "8",
					"messageCid":        "bafycid2",
					"isLatestBaseState": false,
				},
			},
			"cursor":      map[string]any{"streamId": "s1", "epoch": "e1", "position": "8", "messageCid": "bafycid2"},
			"drained":     true,
			"fingerprint": "00ff",
		})
	})

	result, err := client.MessagesQuery(context.Background(), "did:dht:tenant", MessagesQueryOptions{
		Filters: []MessagesFilter{{Protocol: "https://example.com/protocols/mesh"}},
	})
	if err != nil {
		t.Fatalf("MessagesQuery: %v", err)
	}
	if len(result.Entries) != 2 {
		t.Fatalf("entries = %d, want 2", len(result.Entries))
	}
	first := result.Entries[0]
	if first.Seq != "7" || first.MessageCID != "bafycid1" || !first.IsLatestBaseState ||
		first.Protocol != "https://example.com/protocols/mesh" || first.EncodedData != "aGVsbG8" || len(first.Message) == 0 {
		t.Errorf("first entry = %+v", first)
	}
	if second := result.Entries[1]; second.Message != nil || second.IsLatestBaseState {
		t.Errorf("second entry = %+v, want cids-only shape", second)
	}
	if result.Cursor == nil || result.Cursor.Position != "8" || result.Cursor.MessageCID != "bafycid2" {
		t.Errorf("cursor = %+v", result.Cursor)
	}
	if !result.Drained || result.Fingerprint != "00ff" {
		t.Errorf("drained/fingerprint = %v/%q", result.Drained, result.Fingerprint)
	}
}

func TestClientMessagesQueryProgressGap(t *testing.T) {
	client := messagesTestServer(t, func(w http.ResponseWriter, req *JsonRpcRequest) {
		writeJSONRPCReply(w, req.ID, map[string]any{
			"status": map[string]any{"code": 410, "detail": "Progress token gap"},
			"error": map[string]any{
				"code":            "ProgressGap",
				"requested":       map[string]any{"streamId": "s1", "epoch": "old", "position": "5"},
				"oldestAvailable": map[string]any{"streamId": "s1", "epoch": "new", "position": "0"},
				"latestAvailable": map[string]any{"streamId": "s1", "epoch": "new", "position": "9"},
				"reason":          "epoch_mismatch",
			},
		})
	})

	_, err := client.MessagesQuery(context.Background(), "did:dht:tenant", MessagesQueryOptions{
		Cursor: &ProgressToken{StreamID: "s1", Epoch: "old", Position: "5"},
	})
	var gap *ProgressGapError
	if !errors.As(err, &gap) {
		t.Fatalf("error = %v, want *ProgressGapError", err)
	}
	if gap.Info == nil || gap.Info.Reason != "epoch_mismatch" ||
		gap.Info.Requested.Epoch != "old" || gap.Info.LatestAvailable.Position != "9" {
		t.Errorf("gap info = %+v", gap.Info)
	}
}

func TestClientMessagesQueryRateLimited(t *testing.T) {
	client := messagesTestServer(t, func(w http.ResponseWriter, req *JsonRpcRequest) {
		writeJSONRPCReply(w, req.ID, map[string]any{
			"status": map[string]any{"code": 429, "detail": "throttled, retry after 2s"},
		})
	})

	_, err := client.MessagesQuery(context.Background(), "did:dht:tenant", MessagesQueryOptions{})
	if !errors.Is(err, ErrRateLimited) {
		t.Fatalf("error = %v, want ErrRateLimited", err)
	}
}

func TestClientMessagesReadDataTransportSplit(t *testing.T) {
	// Compute a valid CID for the request.
	targetCid, err := ComputeCID(map[string]any{"hello": "world"})
	if err != nil {
		t.Fatalf("ComputeCID: %v", err)
	}
	recordData := []byte("record data bytes")

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var rpcReq JsonRpcRequest
		if err := json.Unmarshal([]byte(r.Header.Get("dwn-request")), &rpcReq); err != nil {
			t.Errorf("parsing dwn-request header: %v", err)
			return
		}
		desc := rpcReq.Params.Message.Descriptor
		if desc["interface"] != "Messages" || desc["method"] != "Read" || desc["messageCid"] != targetCid {
			t.Errorf("descriptor = %v", desc)
		}
		if grantIDs, ok := desc["permissionGrantIds"].([]any); !ok || len(grantIDs) != 1 || grantIDs[0] != "grant-1" {
			t.Errorf("permissionGrantIds = %v", desc["permissionGrantIds"])
		}

		// Data replies: JSON-RPC envelope in the dwn-response header, raw
		// data as the body — same split as RecordsRead.
		envelope, _ := json.Marshal(map[string]any{
			"jsonrpc": "2.0",
			"id":      rpcReq.ID,
			"result": map[string]any{
				"reply": map[string]any{
					"status": map[string]any{"code": 200, "detail": "OK"},
					"entry": map[string]any{
						"messageCid": targetCid,
						"message":    map[string]any{"descriptor": map[string]any{"interface": "Records", "method": "Write"}},
					},
				},
			},
		})
		w.Header().Set("dwn-response", string(envelope))
		_, _ = w.Write(recordData)
	}))
	defer server.Close()

	client := NewClient(server.URL, newTestSigner(t))
	result, err := client.MessagesRead(context.Background(), "did:dht:tenant", targetCid, []string{"grant-1"})
	if err != nil {
		t.Fatalf("MessagesRead: %v", err)
	}
	if result.MessageCID != targetCid {
		t.Errorf("messageCid = %s, want %s", result.MessageCID, targetCid)
	}
	if len(result.Message) == 0 {
		t.Error("message missing")
	}
	if string(result.Data) != string(recordData) {
		t.Errorf("data = %q, want %q", result.Data, recordData)
	}
}

func TestClientMessagesReadNotFound(t *testing.T) {
	targetCid, err := ComputeCID(map[string]any{"missing": true})
	if err != nil {
		t.Fatalf("ComputeCID: %v", err)
	}
	client := messagesTestServer(t, func(w http.ResponseWriter, req *JsonRpcRequest) {
		writeJSONRPCReply(w, req.ID, map[string]any{
			"status": map[string]any{"code": 404, "detail": "Not Found"},
		})
	})

	_, err = client.MessagesRead(context.Background(), "did:dht:tenant", targetCid, nil)
	if !errors.Is(err, ErrMessagesEntryNotFound) {
		t.Fatalf("error = %v, want ErrMessagesEntryNotFound", err)
	}
}
